"use client";

import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
} from "@/components/ui/card";
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import * as z from "zod";
import { useForm } from "react-hook-form";
import React from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { PrimaryButton } from "@/app/components/ButtonPrimary";
import { PasswordInput } from "@/app/components/PasswordInputs";

const schema = z
  .object({
    nomeCompleto: z.string().min(1, {
      message: "Nome completo é obrigatório",
    }),
    email: z.email({ message: "Emaiil inválido" }),
    cpf: z
      .string()
      .trim()
      .min(14, { message: "CPF deve ser formatado por XXX.XXX.XXX-XX" })
      .regex(/^\d{3}\.\d{3}\.\d{3}-\d{2}$/),
    senha: z
      .string()
      .min(6, { message: "Senha deve ter pelo menos 6 caracteres" }),
    confirmarSenha: z.string(),
  })
  .refine((data) => data.senha === data.confirmarSenha, {
    message: "As senhas não coincidem",
    path: ["confirmarSenha"],
  });

type FormData = z.infer<typeof schema>;

function Page() {
  const form = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      nomeCompleto: "",
      email: "",
      cpf: "",
      senha: "",
      confirmarSenha: "",
    },
    mode: "all",
  });

  const onSubmit = async (data: FormData) => {
    console.log("Dados a serem enviados: ", data);
  };

  return (
    <Card
      className="min-w-[326px] w-[30vw] min-h-[326px] h-[90vh]
                  bg-white rounded-[20px] overflow-auto"
      style={{ boxShadow: "4px 4px 10px rgba(0, 0, 0, 0.25)" }}
    >
      <CardHeader className="pt-12">
        <div className="w-full flex justify-center mt-8 sm:mt-12">
          <span className="font-baloo2 font-semibold text-[2.25rem] leading-[58px] text-center text-blue-900">
            Cadastrar
          </span>
        </div>
      </CardHeader>
      <CardContent className="w-full flex justify-center items-start"></CardContent>
      <CardFooter className="w-full flex justify-center">
        <PrimaryButton type="submit">Cadastrar</PrimaryButton>
      </CardFooter>
    </Card>
  );
}

export default Page;
